import{_ as e,o as t,c as r,U as i}from"./chunks/framework.e625a6bf.js";const d=JSON.parse('{"title":"拒绝 AI 焦虑！一个普通程序员的真实 AI 工作流（附成本账单）","description":"","frontmatter":{"title":"拒绝 AI 焦虑！一个普通程序员的真实 AI 工作流（附成本账单）","date":"2026/04/27 18:15:58","summary":"今天不谈宏大叙事，也不贩卖焦虑。只晒真实的账单和工作流，看看 AI 到底是为了提效，还是让我们更累？","config":{"show":true,"top":false,"dir":true,"dirTag":["h3","h4","h5"],"tag":["info","ai"],"valine":true,"valineId":null},"password":false,"outline":[3,5]},"headers":[],"relativePath":"views/blog/ai/2026-0427-拒绝-AI-焦虑一个普通程序员的真实-AI-工作流附成本账单.md","filePath":"views/blog/ai/2026-0427-拒绝-AI-焦虑一个普通程序员的真实-AI-工作流附成本账单.md"}'),n={name:"views/blog/ai/2026-0427-拒绝-AI-焦虑一个普通程序员的真实-AI-工作流附成本账单.md"};function o(l,a,p,s,h,c){return t(),r("div",null,[...a[0]||(a[0]=[i('<h6 id="原文-掘金" tabindex="-1">原文 <a href="https://juejin.cn/post/7615554532698718254" target="_blank" rel="noreferrer">掘金</a> <a class="header-anchor" href="#原文-掘金" aria-label="Permalink to &quot;原文 [掘金](https://juejin.cn/post/7615554532698718254)&quot;">​</a></h6><hr><p><img src="http://cdn.sanghangning.cn/blog/hermes/20260427-181605-885f7597.webp" alt=""></p><p>作为一个没有大厂光环的普通 Node.js 程序员，我最初对 AI 的期待只是“少写两行代码”。</p><p>但当 AI 真的跳出聊天框，我发现事情变得有趣起来了：从辅助开发，到搭建属于自己的“赛博妹妹”，再到零基础写小说。</p><p>今天不谈宏大叙事，也不贩卖焦虑。只晒真实的账单和工作流，看看 AI 到底是为了提效，还是让我们更累？</p><h2 id="我眼中的-ai" tabindex="-1">我眼中的 AI <a class="header-anchor" href="#我眼中的-ai" aria-label="Permalink to &quot;我眼中的 AI&quot;">​</a></h2><p>开始之前，还是先聊聊我自己对 AI 的理解。</p><p>之前在<a href="https://link.juejin.cn?target=https%3A%2F%2Fkonata9.cc%2Fblog%2F2twu1aee%2F" title="https://konata9.cc/blog/2twu1aee/" target="_blank" rel="noreferrer">2025 终于在 AI 代码助手里找到了“Vibe”</a>中谈了 AI 在开发方面带给我的影响。让我逐渐从“写代码”的角色变成“审代码”的角色。</p><p>从 AI 跳出网页聊天框的那一刻起，它就不再只是程序员的助手了。只要打开思路，AI 随时都能在写作、小说创作、图像生成、视频创作上成为你的助力。</p><h2 id="我是如何使用-ai-工具的" tabindex="-1">我是如何使用 AI 工具的 <a class="header-anchor" href="#我是如何使用-ai-工具的" aria-label="Permalink to &quot;我是如何使用 AI 工具的&quot;">​</a></h2><p>作为打工人，工作和非工作时的 AI 工具的使用是完全不同的。</p><p>工作中，会出于合规安全的角度，使用上会有所限制；非工作时处理的任务种类更多，因此 AI 的使用上也更灵活。</p><p>下面分别介绍一下两种状态下的 AI 使用，但后文着重会围绕<strong>非工作</strong>时的使用。</p><h3 id="工作时" tabindex="-1">工作时 <a class="header-anchor" href="#工作时" aria-label="Permalink to &quot;工作时&quot;">​</a></h3><p><img src="http://cdn.sanghangning.cn/blog/hermes/20260427-181606-fe061a4c.webp" alt=""></p><p>工作时的 AI 工具自然是围绕着代码开发展开。出于合规和安全考虑，需要使用公司认为安全的工具。</p><ol><li>Cursor 辅助代码的开发/文档更新/测试用例生成。</li><li>DeepSeek 用来帮助验证想法和资料的搜索。</li><li>Google 用来进一步搜索资料和 AI 给出结果的验证。</li></ol><p>在这里 AI 主要取代的是编码的“体力活”，省出来的更多时间用来打磨系统的设计和需求的理解。</p><h3 id="非工作时" tabindex="-1">非工作时 <a class="header-anchor" href="#非工作时" aria-label="Permalink to &quot;非工作时&quot;">​</a></h3><p><img src="http://cdn.sanghangning.cn/blog/hermes/20260427-181608-4f4b2fdf.webp" alt=""></p><p>非工作时的 AI 工具主要围绕我自己的自媒体展开。AI 工具服务于公众号、小红书、抖音、少数派、掘金等内容创作上。内容以文本为主和代码一样也都存在 Github 上。</p><ol><li><strong>Trae</strong>：辅助代码开发/小说创作/博客润色。<strong>（邪修用法：你以为 IDE 只能写代码？在我的工作流里，Trae 可是我的小说御用编辑...只要脑洞够大，就可以这么玩）。</strong></li><li><strong>OpenClaw（赛博妹妹）</strong>：搜集和创作图文信息/对周刊点评/ GitHub 项目协助管理（给了权限）。</li><li><strong>即梦</strong>：用来生成图文/知识卡片/公众号插图。</li></ol><p>虽然养上了“龙虾”，但同网上经常听到的“龙虾”全自动工作流不同。我不会让 AI 去进行内容的发布甚至是草稿，最后的审核以及发布工作仍由我把控。</p><p>这么做的原因有以下几点：</p><ol><li><strong>内容的审核与修改</strong>。除了防止敏感词出现外，还要对内容进行删减和调整。</li><li><strong>安全考虑</strong>。我不想让 OpenClaw 拥有我社交媒体的权限。万一泄漏，后果很可怕。</li><li><strong>图片质量需要审核</strong>。尽管即梦 4.6 的图片生成能力很强，但仍然会有文字变形、风格不符等问题出现。最终还是需要人工干预。</li><li><strong>Token 成本控制</strong>。AI 工具最大的问题就是每一次对话/任务都会消耗 Token，尤其是图片生成的 Token 更贵。出于此考虑，我会让 AI 生成提示词然后我自己去即梦生成图片。</li></ol><h2 id="如何让-ai-融入自己的工作流" tabindex="-1">如何让 AI 融入自己的工作流 <a class="header-anchor" href="#如何让-ai-融入自己的工作流" aria-label="Permalink to &quot;如何让 AI 融入自己的工作流&quot;">​</a></h2><p>工作流并非一蹴而就，需要不断地迭代和优化。每个工作流的情况与个人习惯也不尽相同，因此需要实际情况实际分析。市面上的模板更多的是一种最佳实践，可以参考然后适配自己。</p><p>我认为，AI 工具最主要的作用是代替重复的工作和弥补能力。</p><p>以我非工作时自媒体内容创作的任务流程举例，以下部分就是可以引入 AI 工具：</p><ol><li><strong>编码</strong>：代替了手工作业（重复性任务）。</li><li><strong>内容搜索和创作</strong>：代替了手动搜索和内容创作（弥补能力、重复性任务）。</li><li><strong>图片生成</strong>：完全拓展了能力（尽管做过<a href="https://link.juejin.cn?target=https%3A%2F%2Fmp.weixin.qq.com%2Fs%3F__biz%3DMzA5MjEzMjg2NA%3D%3D%26mid%3D2247487873%26idx%3D1%26sn%3D113d995aa47037ccae850954ff42032f%26scene%3D21%23wechat_redirect" title="https://mp.weixin.qq.com/s?__biz=MzA5MjEzMjg2NA==&amp;mid=2247487873&amp;idx=1&amp;sn=113d995aa47037ccae850954ff42032f&amp;scene=21#wechat_redirect" target="_blank" rel="noreferrer">切图仔</a>，但我不会作图）。</li><li><strong>小说创作</strong>：完全拓展了能力（我除了有脑洞外，小说方面的语言水平并不高）</li></ol><p>因此可以先对自己的工作流进行一个梳理，找出哪些是重复的工作、哪些需要能力弥补。这些部分通常就可以引入 AI。</p><h2 id="成本披露-ai-真的能赚钱吗" tabindex="-1">成本披露：AI 真的能赚钱吗？ <a class="header-anchor" href="#成本披露-ai-真的能赚钱吗" aria-label="Permalink to &quot;成本披露：AI 真的能赚钱吗？&quot;">​</a></h2><p>给出结论之前，先来看看数据。</p><h3 id="支出" tabindex="-1">支出 <a class="header-anchor" href="#支出" aria-label="Permalink to &quot;支出&quot;">​</a></h3><p>先来一张 2 月 DeepSeek 的费用吧。</p><p><img src="http://cdn.sanghangning.cn/blog/hermes/20260427-181608-884507cb.webp" alt=""></p><p>2 月由于使用上了 OpenClaw，DeepSeek 费用直接飙升到 55 块（大约一周 9.9 的咖啡钱）。这里仅供参考，是多是少需要因人而异（我曾在少数派读到过月订阅 5000 的文章）。</p><p>剩下的就是 Trae 和 即梦 的费用了。</p><ol><li>Trae（国际版）包年费用在 90 刀（每月 7.5 刀）。</li><li>即梦 当时为了 Seedance 2.0 开了包月，月费 69 元 。</li><li>腾讯云 99 的轻量应用，月费 8 元。</li></ol><h3 id="收入" tabindex="-1">收入 <a class="header-anchor" href="#收入" aria-label="Permalink to &quot;收入&quot;">​</a></h3><p>很遗憾，除了公众号忽略不计的流量主收入外，并没有额外的收入。</p><p>所以，就目前来看 <strong>AI 并不能给“普通程序员”的我增加收入</strong>。下一次再看到 AI 副业赚钱的文案时，不妨先冷静思考一下支出和回本周期再做决定。</p><p>而我也一直很好奇，那些“跑通”流程的人是如何覆盖住 Token 成本的（他们用的模型也更好）。</p><h2 id="思考-ai-是提效还是让你更累" tabindex="-1">思考：AI 是提效还是让你更累？ <a class="header-anchor" href="#思考-ai-是提效还是让你更累" aria-label="Permalink to &quot;思考：AI 是提效还是让你更累？&quot;">​</a></h2><p>从结果来看，AI 确实能提效。</p><p>赛博妹妹（OpenClaw）能稳定地提供素材，让我从周更变成将近日更，并且拓展了社交媒体。除了自媒体内容和一些插件开发外，还让我成功创作了两本小说（虽然没有人看）。这些事情或多或少都需要一些专业知识和时间成本，在以前同时做这些是非常困难的。</p><p>但另一方面，提效节省出来的时间投入到新的任务中，除了事情变多，上下文的切换也会很耗精力。如果控制不好这点，就会让人变得更累。</p><p>和“下班后回家是玩游戏还是继续学习”这件事类似，我的朋友中既有认为回去玩游戏是罪恶的；也有认为只要该做的事情做好，放松一下并没有错。</p><p>所以 AI 节省下来的时间和精力，是让自己休息还是进行更多的创作，你又会怎么选择呢？</p><hr><blockquote><p>感谢你阅读到这里</p><p>不妨关注一下同名公众号：此方的手帐</p><p>每周和你分享有趣的技术资讯和好文</p></blockquote>',52)])])}const A=e(n,[["render",o]]);export{d as __pageData,A as default};
